class FastWriter {
    constructor() {
        this.out = [];
    }
    p(object) {
        this.out.push(String(object));
        return this;
    }
    pFormat(format, ...args) {
        // Simple %s / %d replacement
        let i = 0;
        const res = format.replace(/%[sd]/g, () => String(args[i++]));
        this.out.push(res);
        return this;
    }
    pp(...args) {
        this.out.push(args.join(' ') + '\n');
        return this;
    }
    ppIntArray(args) {
        this.out.push(args.join(' ') + '\n');
        return this;
    }
    ppLongArray(args) {
        this.out.push(args.join(' ') + '\n');
        return this;
    }
    ppCharArray(args) {
        this.out.push(args.join(' ') + '\n');
        return this;
    }
    printlnArray(arr) {
        this.out.push(arr.join(' ') + '\n');
    }
    println(object) {
        this.out.push(String(object) + '\n');
        return this;
    }
    close() {
        process.stdout.write(this.out.join(''));
    }
}

class FastScanner {
    constructor() {
        this.buffer = fs.readFileSync(0, 'utf8');
        this.tokens = this.buffer.trim().split(/\s+/);
        this.index = 0;
    }
    hasNext() {
        return this.index < this.tokens.length;
    }
    next() {
        if (!this.hasNext()) throw new Error('NoSuchElementException');
        return this.tokens[this.index++];
    }
    longNext() {
        const s = this.next();
        const n = BigInt(s);
        return n;
    }
    intNext() {
        const s = this.next();
        const n = Number(s);
        if (!Number.isInteger(n)) throw new Error('NumberFormatException');
        return n;
    }
    doubleNext() {
        return parseFloat(this.next());
    }
    nextLongArray(n) {
        const a = new Array(n);
        for (let i = 0; i < n; i++) a[i] = this.longNext();
        return a;
    }
    nextIntArray(n) {
        const a = new Array(n);
        for (let i = 0; i < n; i++) a[i] = this.intNext();
        return a;
    }
    nextDoubleArray(n) {
        const a = new Array(n);
        for (let i = 0; i < n; i++) a[i] = this.doubleNext();
        return a;
    }
}

class TreeSet {
    constructor() {
        this.arr = [];
    }
    add(x) {
        let l = 0, r = this.arr.length;
        while (l < r) {
            const m = (l + r) >> 1;
            if (this.arr[m] < x) l = m + 1;
            else r = m;
        }
        if (this.arr[l] !== x) this.arr.splice(l, 0, x);
    }
    floor(x) {
        let l = 0, r = this.arr.length - 1;
        let ans = null;
        while (l <= r) {
            const m = (l + r) >> 1;
            if (this.arr[m] <= x) {
                ans = this.arr[m];
                l = m + 1;
            } else {
                r = m - 1;
            }
        }
        return ans;
    }
}

const out = new FastWriter();
const inScanner = new FastScanner();

function absInt(a) { return a >= 0 ? a : -a; }
function minInt(...ins) { let m = ins[0]; for (let i = 1; i < ins.length; i++) if (ins[i] < m) m = ins[i]; return m; }
function maxInt(...ins) { let m = ins[0]; for (let i = 1; i < ins.length; i++) if (ins[i] > m) m = ins[i]; return m; }
function sumIntArray(ins) { let total = 0; for (const v of ins) total += v; return total; }

class F {
    constructor() {
        this.n = 0;
        this.m = 0;
        this.arr = [];
        this.required = 0;
        this.typeDays = new Map();
    }

    solver() {
        this.n = inScanner.intNext();
        this.m = inScanner.intNext();
        this.arr = inScanner.nextIntArray(this.n);
        this.required = sumIntArray(this.arr);
        this.typeDays = new Map();

        for (let i = 0; i < this.m; i++) {
            const d = inScanner.intNext();
            const typ = inScanner.intNext();
            if (this.arr[typ - 1] <= 0) continue;
            if (!this.typeDays.has(typ)) this.typeDays.set(typ, new TreeSet());
            this.typeDays.get(typ).add(d);
        }

        let lo = this.required;
        let hi = 2 * this.required;
        let valid = hi;
        while (lo <= hi) {
            const mid = Math.floor((lo + hi) / 2);
            if (this.isEnough(mid)) {
                valid = mid;
                hi = mid - 1;
            } else {
                lo = mid + 1;
            }
        }
        out.println(valid);
    }

    isEnough(day) {
        let totalCoin = day;
        let req = this.required;

        const ddays = new Array(day + 1).fill(0);
        for (const [typ, set] of this.typeDays.entries()) {
            const lastDay = set.floor(day);
            if (lastDay == null) continue;
            ddays[lastDay] += this.arr[typ - 1];
        }

        let removed = 0;
        for (let i = 1; i < day + 1; i++) {
            const coins = i - removed;
            const toRemove = minInt(coins, ddays[i]);
            removed += toRemove;
            totalCoin -= toRemove;
            req -= toRemove;
        }
        return req * 2 <= totalCoin;
    }
}

function main() {
    const solver = new F();
    solver.solver();
    out.close();
}

